// Simple side‑scroll runner
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = 800; canvas.height = 200;

// player
const player = {
  w: 20,
  h: 20,
  x: 50,
  y: canvas.height - 40,
  vy: 0,
  onGround: true,
  slide: false,
};

const GRAVITY = 0.6;
const JUMP_VELOCITY = -12;
const SLIDE_TIME = 15;
let slideTimer = 0;

// obstacles
const obstacles = [];
const OBSTACLE_FREQ = 120; // frames
let frameCount = 0;

function spawnObstacle() {
  const type = Math.random() < 0.5 ? 'spike' : 'bar';
  if (type === 'spike') {
    obstacles.push({x: canvas.width, y: canvas.height - 30, w: 20, h: 20, type});
  } else {
    const h = 40 + Math.random() * 40;
    obstacles.push({x: canvas.width, y: canvas.height - h, w: 20, h, type});
  }
}

function update() {
  frameCount++;
  if (frameCount % OBSTACLE_FREQ === 0) spawnObstacle();

  // player physics
  if (!player.onGround) player.vy += GRAVITY;
  player.y += player.vy;
  if (player.y >= canvas.height - 40) {
    player.y = canvas.height - 40;
    player.vy = 0;
    player.onGround = true;
  }
  // slide timer
  if (slideTimer > 0) {
    slideTimer--;
    if (slideTimer === 0) player.slide = false;
  }

  // move obstacles left
  for (let i = obstacles.length - 1; i >= 0; i--) {
    const o = obstacles[i];
    o.x -= 4;
    // collision
    if (o.x < player.x + player.w && o.x + o.w > player.x &&
        o.y < player.y + player.h && o.y + o.h > player.y) {
      gameOver();
      return;
    }
    // remove off‑screen
    if (o.x + o.w < 0) obstacles.splice(i, 1);
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // ground
  ctx.fillStyle = '#444';
  ctx.fillRect(0, canvas.height - 20, canvas.width, 20);
  // player
  ctx.fillStyle = '#0f0';
  const ph = player.slide ? player.h / 2 : player.h;
  const py = player.slide ? player.y + player.h / 2 : player.y;
  ctx.fillRect(player.x, py, player.w, ph);
  // obstacles
  ctx.fillStyle = '#f00';
  obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
}

let running = true;
function gameOver() {
  running = false;
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  ctx.font = '30px sans-serif';
  ctx.fillText('Game Over', canvas.width/2-80, canvas.height/2);
}

function loop() {
  if (!running) return;
  update();
  draw();
  requestAnimationFrame(loop);
}

// controls
window.addEventListener('keydown', e => {
  if (e.code === 'ArrowUp' && player.onGround && !player.slide) {
    player.vy = JUMP_VELOCITY;
    player.onGround = false;
  }
  if (e.code === 'ArrowDown' && player.onGround && !player.slide) {
    player.slide = true;
    slideTimer = SLIDE_TIME;
  }
});

loop();
